{
  "name": "opencode-vision",
  "version": "0.1.0",
  "description": "An opencode plugin that gives a cheap, text-only model eyes: it asks a vision model one specific question about an image or PDF and returns only what it saw.",
  "type": "module",
  "main": "src/vision.ts",
  "exports": {
    ".": "./src/vision.ts"
  },
  "files": [
    "src",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "vision",
    "ocr",
    "screenshot",
    "multimodal",
    "llm"
  ],
  "license": "MIT",
  "author": "Al Kevin Tan",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alkevintan/opencode-vision.git"
  },
  "bugs": {
    "url": "https://github.com/alkevintan/opencode-vision/issues"
  },
  "homepage": "https://github.com/alkevintan/opencode-vision#readme",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.5"
  }
}
